&lt;span class="o"&gt;&amp;lt;&lt;/span&gt;&lt;span class="nc"&gt;Container&lt;/span&gt; &lt;span class="n"&gt;className&lt;/span&gt;&lt;span class="o"&gt;=&lt;/span&gt;&lt;span class="s2"&gt;"mx-auto max-w-[600px] border border-border p-5"&lt;/span&gt;&lt;span class="o"&gt;&amp;gt;&lt;/span&gt;
